PRICE = {"small": (0.5, 1.5), "large": (5.0, 15.0)}  # 1천 토큰당 (입력, 출력) 원
budget, used = {"hr-team": 100.0}, {"hr-team": 0.0}
def cost(m, tin, tout):
    pi, po = PRICE[m]; return tin / 1000 * pi + tout / 1000 * po
def call(t, m, tin, max_out):
    hold = cost(m, tin, max_out)
    if used[t] + hold > budget[t]:
        return f"429 예산 초과 (사용 {used[t]:.1f} + 예상 {hold:.1f} > {budget[t]:.0f})"
    used[t] += cost(m, tin, max_out // 3)   # 실제로는 덜 썼다고 치자
    return f"200 ok  사용 누계 {used[t]:.1f}원"

for m, tin, mo in [("small", 4000, 2000), ("large", 4000, 2000), ("large", 8000, 4000), ("large", 2000, 1000)]:
    print(m, call("hr-team", m, tin, mo))
# small 200 ok  사용 누계 3.0원
# large 200 ok  사용 누계 33.0원
# large 429 예산 초과 (사용 33.0 + 예상 100.0 > 100)
# large 200 ok  사용 누계 48.0원
